/**
 * Free font library: Google Fonts (SIL OFL, Apache, UFL) and Fontshare (ITF FFL, SIL OFL), both
 * licensed for embedding in web pages and PDFs. A font is stored as a short reference, e.g.
 * "g:Playfair Display" or "fs:satoshi". The catalog (catalog.json) is generated by
 * scripts/font-catalog.mjs from the public metadata of both libraries, no API key needed.
 */

export const fontCategories = ["sans", "serif", "display", "handwriting", "mono"] as const;
export type FontCategory = (typeof fontCategories)[number];

export const fontCategoryLabel: Record<FontCategory, string> = {
  sans: "Sans serif",
  serif: "Serif",
  display: "Display",
  handwriting: "Scrittura a mano",
  mono: "Monospace",
};

export type FontSource = "g" | "fs";
export type FontRef = `${FontSource}:${string}`;

/** One catalog row: reference, family name, category, upright weights, italic weights. */
export type CatalogRow = [string, string, string, number[], number[]];
export type FontEntry = { ref: FontRef; name: string; category: FontCategory; weights: number[]; italics: number[]; source: FontSource };

const refPattern = /^(g:[A-Za-z0-9][A-Za-z0-9 ]{0,60}|fs:[a-z0-9][a-z0-9-]{0,60})$/;

export function isFontRef(value: unknown): value is FontRef {
  return typeof value === "string" && refPattern.test(value);
}

export function parseFontRef(ref: FontRef): { source: FontSource; id: string } {
  const at = ref.indexOf(":");
  return { source: ref.slice(0, at) as FontSource, id: ref.slice(at + 1) };
}

/** CSS / PDF family name of a library font. Unique per source, so two libraries never collide. */
export function fontFamilyName(ref: FontRef): string {
  const { source, id } = parseFontRef(ref);
  return `cqf-${source}-${id.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
}

export function toEntry(row: CatalogRow): FontEntry {
  const [ref, name, category, weights, italics] = row;
  return {
    ref: ref as FontRef,
    name,
    category: (fontCategories as readonly string[]).includes(category) ? (category as FontCategory) : "sans",
    weights,
    italics,
    source: ref.startsWith("fs:") ? "fs" : "g",
  };
}

/** The weights worth loading: every one the family has, at most nine. */
function pick(weights: number[]): number[] {
  return weights.filter((weight) => weight >= 100 && weight <= 900).slice(0, 9);
}

/**
 * Upstream stylesheet of a family. Google answers with WOFF2 to a browser and with TTF to a plain
 * client (the PDF engine needs TTF or WOFF); Fontshare lists WOFF2, WOFF and TTF in one sheet.
 */
export function upstreamCssUrl(entry: FontEntry, options: { preview?: boolean } = {}): string {
  const weights = options.preview ? [nearest(entry.weights, 400)] : pick(entry.weights);
  const italics = options.preview ? [] : pick(entry.italics);
  if (entry.source === "fs") {
    const { id } = parseFontRef(entry.ref);
    const list = [...weights.map(String), ...italics.map((weight) => String(weight + 1))].join(",");
    return `https://api.fontshare.com/v2/css?f[]=${encodeURIComponent(id)}@${list}&display=swap`;
  }
  const family = encodeURIComponent(entry.name).replace(/%20/g, "+");
  if (!italics.length) return `https://fonts.googleapis.com/css2?family=${family}:wght@${weights.join(";")}&display=swap`;
  const tuples = [...weights.map((weight) => `0,${weight}`), ...italics.map((weight) => `1,${weight}`)];
  return `https://fonts.googleapis.com/css2?family=${family}:ital,wght@${tuples.join(";")}&display=swap`;
}

export function nearest(weights: number[], target: number): number {
  let best = weights[0] ?? 400;
  for (const weight of weights) if (Math.abs(weight - target) < Math.abs(best - target)) best = weight;
  return best;
}

export type FontFace = { weight: number; italic: boolean; url: string; format: string; range: string | null };

/** Reads the @font-face rules of an upstream sheet. Protocol-relative URLs become https. */
export function parseFaces(css: string): FontFace[] {
  const faces: FontFace[] = [];
  for (const match of css.matchAll(/@font-face\s*{([^}]*)}/g)) {
    const body = match[1] ?? "";
    const weight = Number(/font-weight:\s*(\d+)/.exec(body)?.[1] ?? 400);
    const italic = /font-style:\s*italic/.test(body);
    const range = /unicode-range:\s*([^;]+);/.exec(body)?.[1]?.trim() ?? null;
    for (const source of body.matchAll(/url\(\s*['"]?([^'")]+)['"]?\s*\)\s*format\(\s*['"]?([a-z0-9]+)['"]?\s*\)/g)) {
      const raw = source[1] ?? "";
      faces.push({ weight, italic, url: raw.startsWith("//") ? `https:${raw}` : raw, format: source[2] ?? "", range });
    }
  }
  return faces;
}

const hosts: Record<FontSource, string> = { g: "https://fonts.gstatic.com/", fs: "https://cdn.fontshare.com/" };

/** Same-origin path of an upstream font file (the app serves them, so no third party sees the visitor). */
export function proxiedFontPath(url: string): string | null {
  for (const [source, host] of Object.entries(hosts)) {
    if (url.startsWith(host)) {
      const rest = url.slice(host.length);
      return fontFilePattern.test(rest) ? `/api/fonts/file/${source}/${rest}` : null;
    }
  }
  return null;
}

export const fontFilePattern = /^[A-Za-z0-9_\-/.]{1,300}\.(woff2|woff|ttf)$/;

export function upstreamFileUrl(source: string, path: string): string | null {
  const host = hosts[source as FontSource];
  if (!host || !fontFilePattern.test(path) || path.includes("..")) return null;
  return `${host}${path}`;
}

/** Same-origin stylesheet: only the WOFF2/WOFF faces, our family name, our file paths. */
export function rewriteCss(ref: FontRef, faces: FontFace[]): string {
  const family = fontFamilyName(ref);
  const rules: string[] = [];
  const seen = new Set<string>();
  for (const face of faces) {
    if (face.format !== "woff2" && face.format !== "woff") continue;
    const key = `${face.weight}:${face.italic}:${face.range ?? ""}`;
    if (seen.has(key)) continue;
    const path = proxiedFontPath(face.url);
    if (!path) continue;
    seen.add(key);
    rules.push(
      `@font-face{font-family:"${family}";font-style:${face.italic ? "italic" : "normal"};font-weight:${face.weight};font-display:swap;src:url(${path}) format("${face.format}");${face.range && /^[U+0-9A-Fa-f, ?-]+$/.test(face.range) ? `unicode-range:${face.range};` : ""}}`,
    );
  }
  return rules.join("\n");
}

/** Stylesheet URL of the app for a set of fonts. */
export function fontCssHref(refs: readonly FontRef[], options: { preview?: boolean } = {}): string | null {
  const list = [...new Set(refs)].sort();
  if (!list.length) return null;
  const params = new URLSearchParams();
  for (const ref of list) params.append("f", ref);
  if (options.preview) params.set("p", "1");
  return `/api/fonts/css?${params.toString()}`;
}
